</style></head><body><header><a href="/admin/website-design">← Website Theme</a><strong>Food &amp; Beverage acceptance</strong><span>Dummy data · No store changes</span></header><main><nav>@foreach($scenarios as $scenario)<button data-scenario="{{ $scenario }}">{{ ['plp'=>'PLP · Product listing','pdp'=>'PDP · Product details'][$scenario] ?? str($scenario)->replace('-',' ')->title() }}</button>@endforeach</nav><section><div class="tools"><button id="desktop">Desktop</button><button id="mobile">Mobile</button><button id="compare">Show approved design</button><a id="open" target="_blank">Open demo ↗</a></div><iframe id="demo" title="Food theme dummy data demo" sandbox="allow-scripts allow-same-origin"></iframe><img id="reference" alt="Approved design reference"></section></main><script>
let selected='plp';const frame=document.querySelector('#demo'),reference=document.querySelector('#reference');
function show(s){selected=s;const url='/admin/website-design/acceptance/sample/'+s;frame.src=url;reference.src='/admin/website-design/acceptance/reference/'+s;document.querySelector('#open').href=url;document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-current',b.dataset.scenario===s));}
document.querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>show(b.dataset.scenario));document.querySelector('#mobile').onclick=()=>frame.style.width='390px';document.querySelector('#desktop').onclick=()=>frame.style.width='100%';document.querySelector('#compare').onclick=()=>{const visible=reference.style.display==='block';reference.style.display=visible?'none':'block';frame.style.display=visible?'block':'none';document.querySelector('#compare').textContent=visible?'Show approved design':'Show demo';};show('plp');
</script></body></html>
